INSERT INTO hsdg.compliance_rules
  (code, name, description, service_id, category, is_active, due_date_category, due_date_source)
SELECT x.code, x.name, x.description, s.id, x.category, true, x.due_date_category, 'LAW_RULE'
FROM jsonb_to_recordset($json$[
{"code":"GST_ITC_RECON_M","name":"Inward reconciliation (monthly)","description":"Purchases and ITC: books vs GSTR-2B after IMS actions, reversals and RCM identified. No return of its own; its end state is Reconciled and its figures feed the 3B. 2B is available on the 14th, so done by the 18th, ahead of the 3B on the 20th.","category":"gst","due_date_category":"HSDG_RECURRING","service_code":"STREAM_GST"},
{"code":"GST_ITC_RECON_Q","name":"Inward reconciliation (QRMP, quarterly)","description":"QRMP purchases and ITC for the quarter, reconciled ahead of the quarterly 3B (22nd / 24th after the quarter).","category":"gst","due_date_category":"HSDG_RECURRING","service_code":"STREAM_GST"},
{"code":"BK_MONTH_CLOSE","name":"Bookkeeping month-close","description":"Data received, bank reconciliation, ledger scrutiny, GST / TDS reconciliation, books closed — by the 15th of the next month, so the month feeds MIS and the 3B checks.","category":"other","due_date_category":"HSDG_RECURRING","service_code":"STREAM_BOOKKEEPING"},
{"code":"MIS_MONTHLY_PACK","name":"MIS pack (monthly)","description":"MIS pack and variance commentary, sent to the client by the 20th of the next month.","category":"other","due_date_category":"HSDG_RECURRING","service_code":"STREAM_MIS"}
]$json$::jsonb)
  AS x(code text, name text, description text, category text, due_date_category text, service_code text)
JOIN hsdg.services s ON s.code = x.service_code
ON CONFLICT (code) DO NOTHING;

INSERT INTO hsdg.compliance_rule_versions
  (compliance_rule_id, version, effective_from, effective_to, calculation_basis, offset_months,
   offset_days, working_day_adjustment, internal_sla_offset_days, condition, notes, stream,
   registration_scope, frequency, form_label, section, schedule, period_overrides, period_filter,
   event_type, provisional_event_rule, variants, is_optional, late_fee_note, verification, source_ref)
SELECT r.id, v.version, v.effective_from, v.effective_to, v.calculation_basis, v.offset_months,
       v.offset_days, 'none', v.internal_sla_offset_days, v.condition, v.notes, v.stream,
       v.registration_scope, v.frequency, v.form_label, v.section, v.schedule, v.period_overrides,
       CASE WHEN v.period_filter IS NULL THEN NULL
            ELSE ARRAY(SELECT jsonb_array_elements_text(v.period_filter)) END,
       v.event_type, v.provisional_event_rule, v.variants, v.is_optional, v.late_fee_note,
       v.verification, v.source_ref
FROM jsonb_to_recordset($json$[
{"code":"GST_ITC_RECON_M","version":1,"effective_from":"2017-04-01","effective_to":null,"calculation_basis":"period_end","offset_months":0,"offset_days":18,"internal_sla_offset_days":2,"condition":{"field":"gst_scheme","op":"==","value":"regular"},"notes":"Purchases and ITC: books vs GSTR-2B after IMS actions, reversals and RCM identified. No return of its own; its end state is Reconciled and its figures feed the 3B. 2B is available on the 14th, so done by the 18th, ahead of the 3B on the 20th.","stream":"gst","registration_scope":"gstin","frequency":"monthly","form_label":"Inward reconciliation","section":"inward","schedule":null,"period_overrides":null,"period_filter":null,"event_type":null,"provisional_event_rule":null,"variants":null,"is_optional":false,"late_fee_note":null,"verification":"verified","source_ref":null},
{"code":"GST_ITC_RECON_Q","version":1,"effective_from":"2017-04-01","effective_to":null,"calculation_basis":"period_end","offset_months":0,"offset_days":18,"internal_sla_offset_days":2,"condition":{"field":"gst_scheme","op":"==","value":"qrmp"},"notes":"QRMP purchases and ITC for the quarter, reconciled ahead of the quarterly 3B (22nd / 24th after the quarter).","stream":"gst","registration_scope":"gstin","frequency":"quarterly","form_label":"Inward reconciliation (QRMP)","section":"inward","schedule":null,"period_overrides":null,"period_filter":null,"event_type":null,"provisional_event_rule":null,"variants":null,"is_optional":false,"late_fee_note":null,"verification":"verified","source_ref":null},
{"code":"BK_MONTH_CLOSE","version":1,"effective_from":"2017-04-01","effective_to":null,"calculation_basis":"period_end","offset_months":0,"offset_days":15,"internal_sla_offset_days":3,"condition":null,"notes":"Data received, bank reconciliation, ledger scrutiny, GST / TDS reconciliation, books closed — by the 15th of the next month, so the month feeds MIS and the 3B checks.","stream":"bookkeeping","registration_scope":"entity","frequency":"monthly","form_label":"Books closed","section":null,"schedule":null,"period_overrides":null,"period_filter":null,"event_type":null,"provisional_event_rule":null,"variants":null,"is_optional":false,"late_fee_note":null,"verification":"verified","source_ref":null},
{"code":"MIS_MONTHLY_PACK","version":1,"effective_from":"2017-04-01","effective_to":null,"calculation_basis":"period_end","offset_months":0,"offset_days":20,"internal_sla_offset_days":3,"condition":null,"notes":"MIS pack and variance commentary, sent to the client by the 20th of the next month.","stream":"mis","registration_scope":"entity","frequency":"monthly","form_label":"MIS pack","section":null,"schedule":null,"period_overrides":null,"period_filter":null,"event_type":null,"provisional_event_rule":null,"variants":null,"is_optional":false,"late_fee_note":null,"verification":"verified","source_ref":null}
]$json$::jsonb)
  AS v(code text, version int, effective_from date, effective_to date, calculation_basis text,
       offset_months int, offset_days int, internal_sla_offset_days int, condition jsonb, notes text,
       stream text, registration_scope text, frequency text, form_label text, section text,
       schedule jsonb, period_overrides jsonb, period_filter jsonb, event_type text,
       provisional_event_rule jsonb, variants jsonb, is_optional boolean, late_fee_note text,
       verification text, source_ref text)
JOIN hsdg.compliance_rules r ON r.code = v.code
ON CONFLICT (compliance_rule_id, version) DO NOTHING;

INSERT INTO hsdg.catalogue_templates (template_type, code, name, description)
