{"code":"FILING_BOOKKEEPING","name":"Bookkeeping — month-close","body":{"items":[{"code":"DATA_RECEIVED","label":"Data received (bank statements, bills, vouchers)","slotCode":"CLIENT_DATA","required":true,"sequence":1,"autoTick":"document","note":"Client data; internal date 5th of next month"},{"code":"BANK_RECON","label":"Bank reconciliation","slotCode":"BANK_RECON","required":true,"sequence":2,"autoTick":"document"},{"code":"LEDGER_SCRUTINY","label":"Ledger scrutiny","required":true,"sequence":3},{"code":"TAX_RECON","label":"GST / TDS reconciliation with the books","slotCode":"TAX_RECON","required":true,"sequence":4,"autoTick":"document"},{"code":"REVIEW","label":"Review","required":true,"sequence":5,"autoTick":"review"},{"code":"LODGE","label":"Books closed","slotCode":"TRIAL_BALANCE","required":true,"sequence":6,"autoTick":"lodge"}]}},
{"code":"FILING_MIS","name":"MIS — monthly pack","body":{"items":[{"code":"BOOKS_CLOSED","label":"Books closed for the month","required":true,"sequence":1,"note":"From the Bookkeeping tab"},{"code":"MIS_PACK","label":"MIS pack prepared","slotCode":"MIS_PACK","required":true,"sequence":2,"autoTick":"document"},{"code":"VARIANCE","label":"Variance commentary written","required":true,"sequence":3},{"code":"REVIEW","label":"Review","required":true,"sequence":4,"autoTick":"review"},{"code":"LODGE","label":"Sent to client","slotCode":"MIS_SENT","required":true,"sequence":5,"autoTick":"lodge"}]}}
